+  localFileInstance.initWithPath(filePath);

-    const outputStream = Cc["@mozilla.org/network/file-output-stream;1"].createInstance(
-      Ci.nsIFileOutputStream
-    );
-    try {
-      outputStream.init(
-        localFileInstance,
-        MODE_WRONLY | MODE_CREATE | MODE_TRUNCATE,
-        parseInt("0664", 8),
